"use client";

import React, { useEffect } from "react";
import { useLocaleStore } from "@/shared/hooks/useLocaleStore";
import { LOCALE_CONFIGS, ALL_LOCALE_HTML_CLASSES, type Locale } from "@/shared/i18n/config";
import { I18nProvider } from "@/shared/i18n/client";

interface LanguageProviderProps {
  children: React.ReactNode;
  initialLocale: Locale;
}

export function LanguageProvider({ children, initialLocale }: LanguageProviderProps) {
  const storeLocale = useLocaleStore((s) => s.locale);
  const setLocale = useLocaleStore((s) => s.setLocale);

  useEffect(() => {
    if (storeLocale !== initialLocale) {
      setLocale(initialLocale);
    }
  }, [initialLocale, setLocale, storeLocale]);

  const activeLocale = initialLocale;

  useEffect(() => {
    const html = document.documentElement;
    const config = LOCALE_CONFIGS[activeLocale];
    html.setAttribute("lang", config.code);
    html.classList.remove(...ALL_LOCALE_HTML_CLASSES);
    html.classList.add(config.htmlClass);
  }, [activeLocale]);

  return <I18nProvider initialLocale={activeLocale}>{children}</I18nProvider>;
}
