import type { TranslationParams } from "./types";

/**
 * Resolves a nested key in a dictionary (e.g. "hero.badge") and interpolates
 * parameters like {count}, {name}, etc.
 */
export function formatMessage(
  dictionary: Record<string, unknown>,
  key: string,
  params?: TranslationParams
): string {
  const parts = key.split(".");
  let current: unknown = dictionary;

  for (const part of parts) {
    if (current && typeof current === "object" && part in (current as Record<string, unknown>)) {
      current = (current as Record<string, unknown>)[part];
    } else {
      // Key not found — return the key itself as fallback
      return key;
    }
  }

  if (typeof current !== "string") {
    return key;
  }

  if (!params) {
    return current;
  }

  return current.replace(/\{(\w+)\}/g, (match, paramName) => {
    if (paramName in params) {
      return String(params[paramName]);
    }
    return match;
  });
}

const BENGALI_DIGITS = ["০", "১", "২", "৩", "৪", "৫", "৬", "৭", "৮", "৯"];

/**
 * Converts English digits (0-9) to Bengali digits (০-৯).
 */
export function toBengaliNumber(val: number | string): string {
  return String(val).replace(/\d/g, (d) => BENGALI_DIGITS[Number(d)] ?? d);
}

/**
 * Formats a number according to the active locale.
 */
export function formatLocalizedNumber(val: number | string, locale: string): string {
  if (locale === "bn") {
    return toBengaliNumber(val);
  }
  return String(val);
}

